    /**
     * Method to retrieve the Agency via AgencyFetchOneSummary
     * @param 	summary AgencyFetchOneSummary 
     * @return 	AgencyFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Agency getAgency( AgencyFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AgencyFetchOneSummary arg cannot be null" );
    	
    	Agency entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Agency
        	// --------------------------------------
        	CompletableFuture<Agency> futureEntity = queryGateway.query(new FindAgencyQuery( new LoadAgencyFilter( summary.getAgencyId() ) ), ResponseTypes.instanceOf(Agency.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Agency with id " + summary.getAgencyId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


